// ============ LissAV 视频书源 · 公共JS库 ============
// 只放不碰 java binding 的纯函数（jsLib 共享 scope 看不到 evalJS 注入的 java）。
// 规则 {{LS_base()}} 内联调用 + loginUrl 面板通过 this.source 读写变量。
// 线路变量唯一真身 = source.setVariable(JSON)（getVariable/setVariable 跨环境共享）。
// 数据结构: {lsZone:"asian"|"domestic", lsLine:"https://xxx", lsLines:"[...]",
//            lsPage:"0", lsSpN:"123ms", lsDiag:"..."}

function LS_getData() {
  var d;
  try { d = this.source.getVariable(); } catch (e) { d = null; }
  if (d === null || d === undefined || d === '') return {};
  try { return JSON.parse(String(d)); } catch (e) { return {}; }
}

function LS_saveData(d) {
  var s = JSON.stringify(d);
  try { this.source.setVariable(s); } catch (e) {}
  return s;
}

// 当前区：asian(日本) | domestic(国产)。默认 asian。
function LS_zone() {
  // 本源只保留日本区(asian)；国产区CDN分片伪装致播放器无法播放，已移除
  return 'asian';
}

// 当前线路根（不含路径）。默认 lissav.sbs。
function LS_line() {
  var d = LS_getData.call(this);
  var l = String(d.lsLine || 'https://lissav.sbs');
  if (l.indexOf('http') !== 0) l = 'https://lissav.sbs';
  return l.replace(/\/+$/, '');
}

// 站点基址 = 线路根 + /{zone}/zh-CN  —— 给 {{LS_base()}} 用（规则里所有站点 URL 的前缀）
function LS_base() {
  return LS_line.call(this) + '/' + LS_zone.call(this) + '/zh-CN';
}

// 面板写线路（双写 setVariable + source.put 保险）
function LS_writeLine(line) {
  var d = LS_getData.call(this);
  d.lsLine = String(line).replace(/\/+$/, '');
  LS_saveData.call(this, d);
  try { this.source.put('lsLine', d.lsLine); } catch (e) {}
  return d.lsLine;
}

// 面板写区
function LS_writeZone(z) {
  var d = LS_getData.call(this);
  d.lsZone = (z === 'domestic') ? 'domestic' : 'asian';
  LS_saveData.call(this, d);
  try { this.source.put('lsZone', d.lsZone); } catch (e) {}
  return d.lsZone;
}

// 线路列表（JSON串存变量里）
function LS_lineList() {
  var d = LS_getData.call(this);
  if (!d.lsLines) return [];
  try { return JSON.parse(String(d.lsLines)); } catch (e) { return []; }
}

function LS_storeLines(lines) {
  var d = LS_getData.call(this);
  d.lsLines = JSON.stringify(lines);
  LS_saveData.call(this, d);
  return lines;
}

