// ============ LissAV 视频书源 · 登录/线路管理面板 ============
// loginUi 的 <js> 与 action 共用本文件（SourceLoginDialog 拼 "$loginJS\n$buttonFunctionJS"）。
// ★铁律：用到 java 的函数必须放这里（jsLib 共享 scope 看不到 evalJS 注入的 java）。
// 发布页输入框名: pub；区: lsZone；线路: lsLine（jsLib 的 LS_* 函数经 this.source 存取，同一真身）

function LS_toast(s, long) {
  try { if (long) java.longToast(s); else java.toast(s); } catch (e) { try { java.toast('' + s); } catch (e2) {} }
}
function LS_reUi() {
  try { java.reLoginView(); } catch (e) { try { java.reLoginView(false); } catch (e2) { try { java.reUiView(false); } catch (e3) {} } }
}

function LS_hdrPanel() {
  return '{"User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36","Accept-Language":"zh-CN,zh;q=0.9"}';
}

// ---- 发布页 → LissAV 线路池（必须定义在 loginUrl：jsLib scope 看不到 java binding）----
function LS_fetchPub() {
  var navs = ['https://x99dh.github.io/', 'https://x99dh.pages.dev/'];
  for (var n = 0; n < navs.length; n++) {
    try {
      var r = java.connect(navs[n], LS_hdrPanel(), 15000);
      var b = r.body() + '';
      var m = b.match(/encodedData\s*=\s*'([^']+)'/);
      if (!m) continue;
      var j = decodeURIComponent(java.base64Decode(m[1]));
      var arr = JSON.parse(j);
      for (var i = 0; i < arr.length; i++) {
        if (String(arr[i].name) === 'LissAV' && arr[i].urls) {
          var out = [];
          for (var k = 0; k < arr[i].urls.length; k++) {
            var u = String(arr[i].urls[k].url || '').replace(/\/+$/, '');
            // 剥掉路径前缀只留线路根
            u = u.replace(/\/(asian|domestic)\/zh-CN.*$/, '');
            if (u.indexOf('http') === 0 && out.indexOf(u) < 0) out.push(u);
          }
          if (out.length) return {lines: out, def: String(arr[i].url || out[0]).replace(/\/(asian|domestic)\/zh-CN.*$/, ''), from: navs[n]};
        }
      }
    } catch (e) {}
  }
  return null;
}

// 并发测速（status.html 2字节 'ok' 判活 + callTime 严格预检），ms 写按钮，最快自动切换
function LS_pickFastest() {
  var list = LS_lineList.call(this);
  if (!list.length) return null;
  var best = -1, bestMs = 999999, tested = 0, lastErr = '', mode = '';
  var i, ms, txt;
  var rs = null;
  try {
    var more = [];
    for (i = 0; i < list.length; i++) {
      more.push(list[i] + '/status.html?t=' + Date.now() + ',{"headers":' + LS_hdrPanel() + ',"retry":0}');
    }
    rs = java.ajaxAll(more, true);
    var n = (rs && (rs.length || (rs.size ? rs.size() : 0))) || 0;
    var rsOk = false;
    try {
      var ct0 = parseInt(rs[0].callTime(), 10);
      var bd0 = String(rs[0].body() || '');
      rsOk = (n >= list.length && ct0 > 0 && bd0.indexOf('Exception') < 0 && bd0.indexOf('timeout') < 0);
    } catch (eChk) { rsOk = false; }
    if (rsOk) {
      mode = 'ajaxAll';
      for (i = 0; i < n; i++) {
        ms = 999999; txt = '';
        try { ms = parseInt(rs[i].callTime(), 10); } catch (e) {}
        try { txt = String(rs[i].body() || ''); } catch (e2) {}
        if (txt.trim() !== 'ok' || ms > 15000 || ms < 0) ms = 999999;
        try { this.source.put('lsSp' + i, ms === 999999 ? '超时' : ms + 'ms'); } catch (e9) {}
        if (ms < 15000) tested++;
        if (ms < bestMs) { bestMs = ms; best = i; }
      }
    } else { rs = null; }
  } catch (e) { lastErr = 'ajaxAll:' + String(e).substring(0, 40); rs = null; }
  if (!rs) {
    mode = 'connect';
    for (i = 0; i < list.length; i++) {
      ms = 999999; txt = '';
      try {
        var r = java.connect(list[i] + '/status.html?t=' + Date.now(), LS_hdrPanel(), 6000);
        var ct = 0; try { ct = parseInt(r.callTime(), 10); } catch (e3) {}
        try { txt = String(r.body() || ''); } catch (e4) {}
        if (txt.trim() === 'ok' && ct >= 0) ms = ct;
      } catch (e5) { lastErr = 'connect:' + String(e5).substring(0, 40); }
      try { this.source.put('lsSp' + i, ms === 999999 ? '超时' : ms + 'ms'); } catch (e6) {}
      if (ms < 15000) tested++;
      if (ms < bestMs) { bestMs = ms; best = i; }
    }
  }
  try { this.source.put('lsDiag', 'mode=' + mode + ' tested=' + tested + ' best=' + best + ' err=' + lastErr); } catch (e7) {}
  if (best >= 0 && bestMs < 15000) {
    LS_writeLine.call(this, String(list[best]));
    return {best: best, line: String(list[best]), ms: bestMs, tested: tested};
  }
  return null;
}

// 🧭 一键从发布页获取线路（获取后自动测速选最快）
function LS_actionFetch() {
  LS_toast('🧭 正在解析发布页 x99dh 线路…', true);
  try {
    var res = LS_fetchPub();
    if (!res || !res.lines || !res.lines.length) {
      LS_toast('❌ 未解析到线路，检查网络或稍后再试', true);
      return;
    }
    LS_storeLines.call(this, res.lines);
    var d = LS_getData.call(this);
    d.lsPage = '0';
    LS_saveData.call(this, d);
    LS_writeLine.call(this, String(res.def || res.lines[0]));
    LS_toast('✅ 获取 ' + res.lines.length + ' 条线路，正在测速选最快…', true);
    var fast = LS_pickFastest.call(this);
    if (fast) {
      LS_toast('⚡ 已选最快：' + fast.line.replace(/^https?:\/\//, '') + ' ' + fast.ms + 'ms（' + fast.tested + '条）', true);
    } else {
      LS_toast('✅ 线路已获取（自动测速失败，可点⏱手动测）', true);
    }
    LS_reUi();
  } catch (e) { LS_toast('❌ 解析失败：' + String(e).substring(0, 60), true); }
}

// ⏱ 测速（并发 ajaxAll），ms 写按钮
function LS_actionTest() {
  var list = LS_lineList.call(this);
  if (!list.length) { LS_toast('⚠️ 请先点🧭获取线路', true); return; }
  LS_toast('⏱ 正在测速 ' + list.length + ' 条线路…', true);
  var fast = LS_pickFastest.call(this);
  if (fast) {
    LS_toast('⚡ 最快：' + fast.line.replace(/^https?:\/\//, '') + ' ' + fast.ms + 'ms（' + fast.tested + '条，已切换）', true);
  } else {
    LS_toast('⚠️ 全部线路测速失败，请检查网络', true);
  }
  LS_reUi();
}



// 线路按钮动态文本：▶当前 + ⚡ms + 域名
function LS_lineBtn(i) {
  try {
    var list = LS_lineList.call(this);
    var page = parseInt(LS_getData.call(this).lsPage || '0', 10);
    var idx = page * 12 + i;
    if (idx >= list.length) return '　（空）';
    var u = String(list[idx]).replace(/^https?:\/\//, '').replace(/\/+$/, '');
    var sp = this.source.get('lsSp' + idx) || '';
    var cur = (LS_line.call(this) === String(list[idx]).replace(/\/+$/, '')) ? '▶' : '　';
    var label = cur + (sp ? '⚡' + sp + ' ' : '') + u;
    if (label.length > 19) label = label.substring(0, 19);
    return label;
  } catch (e) { return '　线路' + i; }
}
function LS_pageLabel() {
  try {
    var d = LS_getData.call(this);
    var list = LS_lineList.call(this);
    var page = parseInt(d.lsPage || '0', 10);
    return '　线路 ' + (page + 1) + '/' + Math.max(1, Math.ceil(list.length / 12));
  } catch (e) { return '　线路 1'; }
}

// 各线路切换按钮 action（12个一页，配合 lsPage 翻页）
function LS_switch0()  { return LS_switchIdx.call(this, 0); }
function LS_switch1()  { return LS_switchIdx.call(this, 1); }
function LS_switch2()  { return LS_switchIdx.call(this, 2); }
function LS_switch3()  { return LS_switchIdx.call(this, 3); }
function LS_switch4()  { return LS_switchIdx.call(this, 4); }
function LS_switch5()  { return LS_switchIdx.call(this, 5); }
function LS_switch6()  { return LS_switchIdx.call(this, 6); }
function LS_switch7()  { return LS_switchIdx.call(this, 7); }
function LS_switch8()  { return LS_switchIdx.call(this, 8); }
function LS_switch9()  { return LS_switchIdx.call(this, 9); }
function LS_switch10() { return LS_switchIdx.call(this, 10); }
function LS_switch11() { return LS_switchIdx.call(this, 11); }
function LS_switchIdx(i) {
  var list = LS_lineList.call(this);
  var page = parseInt(LS_getData.call(this).lsPage || '0', 10);
  var idx = page * 12 + i;
  if (idx >= list.length) { LS_toast('⚠️ 该位置无线路，请先🧭获取', true); return; }
  LS_writeLine.call(this, String(list[idx]));
  LS_toast('✅ 已切换线路：' + String(list[idx]).replace(/^https?:\/\//, ''), true);
  LS_reUi();
}

// 线路翻页
function LS_nextPage() {
  var d = LS_getData.call(this);
  var list = LS_lineList.call(this);
  var page = parseInt(d.lsPage || '0', 10);
  var max = Math.max(1, Math.ceil(list.length / 12));
  d.lsPage = String((page + 1) % max);
  LS_saveData.call(this, d);
  LS_toast('📄 线路第 ' + (parseInt(d.lsPage, 10) + 1) + '/' + max + ' 页', false);
  LS_reUi();
}

// 🔍 检查登录状态（本站游客可看，探测当前线路当前区是否可达）
function LS_actionCheck() {
  LS_toast('🔍 正在检查当前线路…', true);
  try {
    var u = LS_base.call(this) + '/videos/new-releases';
    var r = java.connect(u, LS_hdrPanel(), 15000);
    var b = r.body() + '';
    var ok = b.indexOf('streamit-video-card') >= 0;
    var ms = 0; try { ms = parseInt(r.callTime(), 10); } catch (e) {}
    if (ok) LS_toast('✅ 线路正常（游客可用，无登录）' + (ms ? ' ' + ms + 'ms' : ''), true);
    else if ((b + '').length > 500) LS_toast('⚠️ 线路有响应但内容异常，建议测速换线', true);
    else LS_toast('⚠️ 线路异常，建议⏱测速换线', true);
  } catch (e) { LS_toast('❌ 检查失败：' + String(e).substring(0, 50), true); }
}

// 点 √ 必须实现，否则报错
function login() { LS_toast('ℹ️ 本站游客可用，线路设置已保存', false); }
